//   Dell writes `0x0140_3AB0[2:0]=0` (GIGABYTE 7); GIGABYTE numbers the entry
//   types one lower (GIGABYTE type = Dell type - 1 for Dell types >= 3; NBIO.md
//   implementation notes).
// Everything else is byte-identical in both donors.
//! The WH NBIO vendor register tables (NbioBaseConfigurationWh, NbioIommuInitWh,
//! NbioNbifInitSilWh, MpioPerfAnalysis, AmdNbioDxe NbioRASControl). Per-RB tables are
//! applied with the offset `iohc << 20` (`iohc` = IOHC instance on its IOD), absolute
//! ones with 0 (see each table's gate). Nested property tables are flattened with
//! their property merged into each record. Record order is the vendor's. Bits
//! without known meaning stay raw (see [`crate::table`]).
use super::{PerfRecord, Record};
use crate::smn::SmnReg;
use crate::table;

const fn rmw(address: u32, clear: u32, set: u32, property: u32) -> Record {
    table::rmw(SmnReg::new(address), clear, set).when(property)
}
const fn wr(address: u32, value: u32, property: u32) -> Record {
    table::write(SmnReg::new(address), value).when(property)
}
const fn perf(
    group: u8, kind: u8, scope: u8, latency: bool, address: u32, clear: u32, set: u32,
) -> PerfRecord {
    PerfRecord { group, kind, scope, latency, address, clear, set }
}

